#!/usr/bin/env python3
"""Makes PMPA's test samples, all synthetic: signals generated by ffmpeg's
lavfi sources (tones and noise), encoded by lame, twolame and ffmpeg's
encoders, and Layer I written by this script (no encoder at hand makes it).
Nothing here comes from a real recording, so the samples' license is PMPA's.

    scripts/mksamples.py [tests]

Needs ffmpeg (with libmp3lame, libshine, mp2), lame and twolame. The output
depends on those tools' versions: the samples are committed, and this script
says how they were made rather than promising the same bytes again.

    tests/mp3   Layer III: every version, CBR, VBR, ABR, free format, CRC,
                mono, dual channel, with and without the LAME/Xing frame
    tests/mp2   Layer II: MPEG-1 and MPEG-2, the modes, CRC, free format
    tests/mp1   Layer I: MPEG-1 and MPEG-2, the modes (joint stereo too), CRC
    tests/odd   what real files carry around the frames: tags of every kind,
                junk before, between and after, a frame cut short,
                concatenated streams, bytes that are not MPEG at all
"""
import os, random, shutil, struct, subprocess, sys, tempfile

OUT = sys.argv[1] if len(sys.argv) > 1 else 'tests'
TMP = tempfile.mkdtemp(prefix='pmpa-samples-')


def run(*cmd):
    subprocess.run(cmd, check=True, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)


def wav(name, rate, channels, seconds=1.0):
    """A tone, a sweep and some noise: synthetic, but not trivially compressible."""
    path = os.path.join(TMP, f'{name}.wav')
    left = f'0.3*sin(2*PI*440*t)+0.2*sin(2*PI*(200+900*t)*t)+0.05*(random(1)-0.5)'
    right = f'0.25*sin(2*PI*660*t)+0.15*sin(2*PI*3000*t)*sin(2*PI*2*t)+0.05*(random(2)-0.5)'
    expr = left if channels == 1 else f'{left}|{right}'
    run('ffmpeg', '-y', '-v', 'error', '-f', 'lavfi', '-i',
        f'aevalsrc={expr}:s={rate}:d={seconds}', '-c:a', 'pcm_s16le', path)
    return path


def read(path):
    with open(path, 'rb') as f:
        return f.read()


def write(sub, name, data):
    d = os.path.join(OUT, sub)
    os.makedirs(d, exist_ok=True)
    with open(os.path.join(d, name), 'wb') as f:
        f.write(data)


def lame(sub, name, rate, channels, *opts, seconds=1.0):
    src = wav(f'{name}-src', rate, channels, seconds)
    dst = os.path.join(TMP, name)
    run('lame', '--quiet', *opts, src, dst)
    write(sub, name, read(dst))
    return read(dst)


def twolame(sub, name, rate, channels, *opts):
    src = wav(f'{name}-src', rate, channels)
    dst = os.path.join(TMP, name)
    run('twolame', '--quiet', *opts, src, dst)
    write(sub, name, read(dst))
    return read(dst)


def ffmpeg_enc(sub, name, rate, channels, codec, *opts):
    src = wav(f'{name}-src', rate, channels)
    dst = os.path.join(TMP, name)
    run('ffmpeg', '-y', '-v', 'error', '-i', src, '-c:a', codec, *opts, '-f',
        'mp3' if codec != 'mp2' else 'mp2', dst)
    write(sub, name, read(dst))
    return read(dst)


# ---------------------------------------------------------------- Layer I

L1_RATES = {1: {44100: 0, 48000: 1, 32000: 2}, 2: {22050: 0, 24000: 1, 16000: 2}}
L1_BITRATES = {1: [0, 32, 64, 96, 128, 160, 192, 224, 256, 288, 320, 352, 384, 416, 448],
               2: [0, 32, 48, 56, 64, 80, 96, 112, 128, 144, 160, 176, 192, 224, 256]}


class Bits:
    def __init__(self):
        self.bits = []

    def put(self, value, n):
        for i in range(n - 1, -1, -1):
            self.bits.append((value >> i) & 1)

    def tobytes(self, nbytes):
        b = self.bits + [0] * (nbytes * 8 - len(self.bits))
        assert len(b) == nbytes * 8
        return bytes(int(''.join(map(str, b[i:i + 8])), 2) for i in range(0, len(b), 8))


def crc16(bits):
    """MPEG audio's CRC-16: polynomial 0x8005, start 0xFFFF."""
    crc = 0xFFFF
    for bit in bits:
        top = (crc >> 15) & 1
        crc = (crc << 1) & 0xFFFF
        if top ^ bit:
            crc ^= 0x8005
    return crc


def layer1(name, version, rate, kbps, mode, frames, crc=False, mode_ext=0, seed=1):
    """A structurally valid Layer I stream: random bit allocations,
    scalefactors and samples within each frame's budget, the padding a real
    encoder would choose, the CRC when asked, zeros as ancillary data."""
    rng = random.Random(seed)
    nch = 1 if mode == 3 else 2
    bound = 4 * (mode_ext + 1) if mode == 1 else 32
    bri = L1_BITRATES[version].index(kbps)
    out = bytearray()
    frac = 0
    for _ in range(frames):
        frac += 12 * kbps * 1000 % rate
        pad = 0
        if frac >= rate:
            pad, frac = 1, frac - rate
        nbytes = (12 * kbps * 1000 // rate + pad) * 4
        hdr = (0x7FF << 21) | ((3 if version == 1 else 2) << 19) | (3 << 17) \
            | ((0 if crc else 1) << 16) | (bri << 12) | (L1_RATES[version][rate] << 10) \
            | (pad << 9) | (mode << 6) | (mode_ext << 4) | (1 << 2)
        budget = nbytes * 8 - 32 - (16 if crc else 0)
        # allocation: the low subbands get more bits, within the budget
        alloc = [[0] * 2 for _ in range(32)]
        cost = sum(4 * (nch if sb < bound else 1) for sb in range(32))
        for sb in range(32):
            chans = range(nch) if sb < bound else [0]
            for ch in chans:
                want = rng.randint(0, max(0, 8 - sb // 4)) if rng.random() < 0.8 else 0
                while want:
                    c = 6 + 12 * (want + 1) if sb < bound else 6 * nch + 12 * (want + 1)
                    if cost + c <= budget:
                        cost += c
                        break
                    want -= 1
                alloc[sb][ch] = want
            if sb >= bound:
                alloc[sb][1] = alloc[sb][0]
        b = Bits()
        b.put(hdr, 32)
        for sb in range(32):
            for ch in (range(nch) if sb < bound else [0]):
                b.put(alloc[sb][ch], 4)
        if crc:
            protected = [int(x) for x in format(hdr & 0xFFFF, '016b')] + b.bits[32:]
            b.bits[32:32] = [int(x) for x in format(crc16(protected), '016b')]
        for sb in range(32):
            for ch in range(nch):
                if alloc[sb][ch]:
                    b.put(rng.randint(0, 62), 6)
        for _s in range(12):
            for sb in range(32):
                for ch in (range(nch) if sb < bound else [0]):
                    a = alloc[sb][ch]
                    if a:
                        b.put(rng.randint(0, (1 << (a + 1)) - 2), a + 1)
        assert len(b.bits) <= nbytes * 8, (len(b.bits), nbytes)
        out += b.tobytes(nbytes)
    write('mp1', name, bytes(out))
    return bytes(out)


# ---------------------------------------------------------------- tags

def id3v2(size=300, version=3, footer=False):
    body = b'TIT2' + struct.pack('>I', 12) + b'\0\0' + b'\x03synthetic\0' \
        + b'TPE1' + struct.pack('>I', 5) + b'\0\0' + b'\x03pmpa'
    body += b'\0' * max(0, size - len(body))
    n = len(body)
    ss = bytes([(n >> 21) & 127, (n >> 14) & 127, (n >> 7) & 127, n & 127])
    flags = 0x10 if footer else 0
    head = b'ID3' + bytes([version, 0, flags]) + ss
    return head + body + ((b'3DI' + bytes([version, 0, flags]) + ss) if footer else b'')


def id3v1():
    return b'TAG' + b'synthetic'.ljust(30, b'\0') + b'pmpa'.ljust(30, b'\0') \
        + b'tests'.ljust(30, b'\0') + b'2026' + b'made by mksamples'.ljust(28, b'\0') \
        + b'\0\x01' + b'\x0c'


def ape(header=True):
    item = struct.pack('<II', 9, 0) + b'Title\0' + b'synthetic'
    size = len(item) + 32
    # bit 31: the tag has a header; bit 29: this is the header
    flags = 0x80000000 if header else 0
    foot = b'APETAGEX' + struct.pack('<IIII', 2000, size, 1, flags) + b'\0' * 8
    head = b'APETAGEX' + struct.pack('<IIII', 2000, size, 1, flags | 0x20000000) + b'\0' * 8
    return (head if header else b'') + item + foot


def lyrics3():
    body = b'LYRICSBEGIN' + b'IND00002' + b'10' + b'ETT00009synthetic'
    return body + b'%06d' % len(body) + b'LYRICS200'


def main():
    for sub in ('mp1', 'mp2', 'mp3', 'odd'):
        os.makedirs(os.path.join(OUT, sub), exist_ok=True)

    # Layer III
    base = lame('mp3', 'l3_cbr128_44k_joint.mp3', 44100, 2, '-b', '128')
    lame('mp3', 'l3_vbr_v4_44k.mp3', 44100, 2, '-V', '4')
    lame('mp3', 'l3_abr96_48k.mp3', 48000, 2, '--abr', '96')
    lame('mp3', 'l3_cbr32_mono_32k.mp3', 32000, 1, '-m', 'm', '-b', '32')
    lame('mp3', 'l3_cbr160_stereo_crc.mp3', 44100, 2, '-m', 's', '-b', '160', '-p')
    lame('mp3', 'l3_cbr96_dual.mp3', 44100, 2, '-m', 'd', '-b', '96')
    lame('mp3', 'l3_cbr256_nores.mp3', 48000, 2, '-b', '256', '--nores')
    lame('mp3', 'l3_free200_44k.mp3', 44100, 2, '--freeformat', '-b', '200')
    lsf = lame('mp3', 'l3_mpeg2_64k_22k.mp3', 22050, 2, '-b', '64')
    lame('mp3', 'l3_mpeg2_vbr_16k_mono.mp3', 16000, 1, '-m', 'm', '-V', '6')
    lame('mp3', 'l3_mpeg25_16k_8k.mp3', 8000, 1, '-m', 'm', '-b', '16')
    lame('mp3', 'l3_mpeg25_32k_12k_crc.mp3', 12000, 2, '-b', '32', '-p')
    ffmpeg_enc('mp3', 'l3_shine_128k_44k.mp3', 44100, 2, 'libshine', '-b:a', '128k')
    ffmpeg_enc('mp3', 'l3_ffmpeg_lame_vbr.mp3', 44100, 2, 'libmp3lame', '-q:a', '5')

    # Layer II
    twolame('mp2', 'l2_192k_48k_stereo.mp2', 48000, 2, '-b', '192', '-m', 's')
    twolame('mp2', 'l2_256k_44k_joint.mp2', 44100, 2, '-b', '256', '-m', 'j')
    twolame('mp2', 'l2_64k_32k_mono_crc.mp2', 32000, 1, '-b', '64', '-m', 'm', '-p')
    twolame('mp2', 'l2_dual_192k.mp2', 44100, 2, '-b', '192', '-m', 'd')
    twolame('mp2', 'l2_mpeg2_80k_24k.mp2', 24000, 2, '-b', '80')
    twolame('mp2', 'l2_mpeg2_32k_16k_mono.mp2', 16000, 1, '-b', '32', '-m', 'm')
    twolame('mp2', 'l2_free_200k.mp2', 44100, 2, '--freeformat', '-b', '200')
    twolame('mp2', 'l2_vbr_48k.mp2', 48000, 2, '-V', '5')
    ffmpeg_enc('mp2', 'l2_ffmpeg_224k_44k.mp2', 44100, 2, 'mp2', '-b:a', '224k')

    # Layer I
    layer1('l1_192k_44k_stereo.mp1', 1, 44100, 192, 0, 100, seed=1)
    layer1('l1_384k_48k_joint.mp1', 1, 48000, 384, 1, 100, mode_ext=2, seed=2)
    layer1('l1_64k_32k_mono_crc.mp1', 1, 32000, 64, 3, 80, crc=True, seed=3)
    layer1('l1_dual_256k_crc.mp1', 1, 44100, 256, 2, 80, crc=True, seed=4)
    layer1('l1_mpeg2_96k_22k.mp1', 2, 22050, 96, 0, 80, seed=5)
    layer1('l1_mpeg2_32k_16k_mono.mp1', 2, 16000, 32, 3, 60, seed=6)

    # Around the frames
    rng = random.Random(7)
    junk = bytes(rng.randrange(256) for _ in range(1000))
    write('odd', 'junk_before.mp3', junk + base)
    write('odd', 'junk_after.mp3', base + junk)
    # junk somewhere in the middle (a frame boundary or not)
    write('odd', 'junk_between.mp3', base[:4180] + junk + base[4180:])
    write('odd', 'cut_short.mp3', base[:len(base) - 200])
    write('odd', 'id3v2_id3v1.mp3', id3v2(300) + base + id3v1())
    write('odd', 'id3v24_footer_padding.mp3', id3v2(500, 4, footer=True) + b'\0' * 64 + base)
    write('odd', 'two_id3v2.mp3', id3v2(200) + id3v2(100, 4) + base)
    write('odd', 'ape_lyrics_id3v1.mp3', base + lyrics3() + ape() + id3v1())
    write('odd', 'ape_no_header.mp3', base + ape(header=False))
    write('odd', 'concat_44k_22k.mp3', base + lsf)
    write('odd', 'concat_with_id3v2.mp3', base + id3v2(150) + lsf)
    write('odd', 'one_frame.mp3', base[:417])
    write('odd', 'not_mpeg.bin', bytes(rng.randrange(256) for _ in range(20000)))
    write('odd', 'empty_ish.mp3', b'\xff\xfb')


if __name__ == '__main__':
    try:
        main()
    finally:
        shutil.rmtree(TMP, ignore_errors=True)
